func (e *executableSchema) Exec(ctx context.Context) graphql.ResponseHandler {
	opCtx := graphql.GetOperationContext(ctx)
	ec := newExecutionContext(opCtx, e, make(chan graphql.DeferredResult))
	inputUnmarshalers := func() *graphql.InputUnmarshalerIndex {
		return graphql.NewInputUnmarshalerIndex(
			graphql.NewInputUnmarshaler("CreateViewFieldInput", ec.unmarshalInputCreateViewFieldInput),
			graphql.NewInputUnmarshaler("CreateViewFilterGroupInput", ec.unmarshalInputCreateViewFilterGroupInput),
			graphql.NewInputUnmarshaler("CreateViewFilterInput", ec.unmarshalInputCreateViewFilterInput),
			graphql.NewInputUnmarshaler("CreateViewGroupInput", ec.unmarshalInputCreateViewGroupInput),
			graphql.NewInputUnmarshaler("CreateViewInput", ec.unmarshalInputCreateViewInput),
			graphql.NewInputUnmarshaler("CreateViewSortInput", ec.unmarshalInputCreateViewSortInput),
			graphql.NewInputUnmarshaler("DestroyViewFieldInput", ec.unmarshalInputDestroyViewFieldInput),
			graphql.NewInputUnmarshaler("DestroyViewFilterInput", ec.unmarshalInputDestroyViewFilterInput),
			graphql.NewInputUnmarshaler("DestroyViewSortInput", ec.unmarshalInputDestroyViewSortInput),
			graphql.NewInputUnmarshaler("UpdateViewFieldInput", ec.unmarshalInputUpdateViewFieldInput),
			graphql.NewInputUnmarshaler("UpdateViewFieldInputUpdates", ec.unmarshalInputUpdateViewFieldInputUpdates),
			graphql.NewInputUnmarshaler("UpdateViewFilterGroupInput", ec.unmarshalInputUpdateViewFilterGroupInput),
			graphql.NewInputUnmarshaler("UpdateViewFilterInput", ec.unmarshalInputUpdateViewFilterInput),
			graphql.NewInputUnmarshaler("UpdateViewFilterInputUpdates", ec.unmarshalInputUpdateViewFilterInputUpdates),
			graphql.NewInputUnmarshaler("UpdateViewGroupInput", ec.unmarshalInputUpdateViewGroupInput),
			graphql.NewInputUnmarshaler("UpdateViewGroupInputUpdates", ec.unmarshalInputUpdateViewGroupInputUpdates),
			graphql.NewInputUnmarshaler("UpdateViewInput", ec.unmarshalInputUpdateViewInput),
			graphql.NewInputUnmarshaler("UpdateViewSortInput", ec.unmarshalInputUpdateViewSortInput),
			graphql.NewInputUnmarshaler("UpdateViewSortInputUpdates", ec.unmarshalInputUpdateViewSortInputUpdates),
		)
	}
	first := true

	switch opCtx.Operation.Operation {
	case ast.Query:
		return func(ctx context.Context) *graphql.Response {
			var response graphql.Response
			var data graphql.Marshaler
			if first {
				first = false
				ctx = graphql.WithLazyInputUnmarshalerIndex(ctx, inputUnmarshalers)
				data = ec._Query(ctx, opCtx.Operation.SelectionSet)
			} else {
				if atomic.LoadInt32(&ec.PendingDeferred) > 0 {
					result := <-ec.DeferredResults
					atomic.AddInt32(&ec.PendingDeferred, -1)
					data = result.Result
					response.Path = result.Path
					response.Label = result.Label
					response.Errors = result.Errors
				} else {
					return nil
				}
			}
			var buf bytes.Buffer
			data.MarshalGQL(&buf)
			response.Data = buf.Bytes()
			if atomic.LoadInt32(&ec.Deferred) > 0 {
				hasNext := atomic.LoadInt32(&ec.PendingDeferred) > 0
				response.HasNext = &hasNext
			}

			return &response
		}
	case ast.Mutation:
		return func(ctx context.Context) *graphql.Response {
			if !first {
				return nil
			}
			first = false
			ctx = graphql.WithLazyInputUnmarshalerIndex(ctx, inputUnmarshalers)
			data := ec._Mutation(ctx, opCtx.Operation.SelectionSet)
			var buf bytes.Buffer
			data.MarshalGQL(&buf)

			return &graphql.Response{
				Data: buf.Bytes(),
			}
		}

	default:
		return graphql.OneShot(graphql.ErrorResponse(ctx, "unsupported GraphQL operation"))
	}
}

type executionContext struct {
	*graphql.ExecutionContextState[ResolverRoot, DirectiveRoot, ComplexityRoot]
}

func newExecutionContext(
	opCtx *graphql.OperationContext,
	execSchema *executableSchema,
	deferredResults chan graphql.DeferredResult,
) *executionContext {
	return &executionContext{
		ExecutionContextState: graphql.NewExecutionContextState[ResolverRoot, DirectiveRoot, ComplexityRoot](
			opCtx,
			(*graphql.ExecutableSchemaState[ResolverRoot, DirectiveRoot, ComplexityRoot])(execSchema),
			parsedSchema,
			deferredResults,
		),
	}
}

